    public boolean canUse() {
        if (this.crusher.getTarget() != null) {
            return false;
        }
        if (this.crusher.isStaying()) {
            return false;
        }
        if (!(this.crusher.level instanceof ServerLevel)) {
            return false;
        }
        return this.findAllyNeedingWeapon() != null;
    }

